From 5d17a7438ff0551a595afd8dc4052844da6537a5 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 17:48:58 +0100
Subject: [PATCH] microphoneindicator: show the microphone volume in the
 tooltip

The microphone tray icon's tooltip only said "Microphone", while the
volume icon's tooltip shows the current volume and updates while
scrolling on it. Show "Microphone volume at N%" in the same way.

BUG: 526463
---
 src/qml/microphoneindicator.cpp | 5 ++++-
 1 file changed, 4 insertions(+), 1 deletion(-)

diff --git a/src/qml/microphoneindicator.cpp b/src/qml/microphoneindicator.cpp
index 4cfb996e..4987c22a 100644
--- a/src/qml/microphoneindicator.cpp
+++ b/src/qml/microphoneindicator.cpp
@@ -141,11 +141,14 @@ void MicrophoneIndicator::update()
     const bool allMuted = muted();

     QString iconName;
+    QString toolTipTitle = i18n("Microphone");
     if (allMuted) {
         iconName = QStringLiteral("microphone-sensitivity-muted");
+        toolTipTitle = i18n("Microphone Muted");
     } else {
         if (Source *defaultSource = m_preferredDevice.source()) {
             const int percent = volumePercent(defaultSource);
+            toolTipTitle = i18n("Microphone volume at %1%", percent);
             iconName = QStringLiteral("microphone-sensitivity");
             // it deliberately never shows the "muted" icon unless *all* microphones are muted
             if (percent <= 25) {
@@ -166,7 +169,7 @@ void MicrophoneIndicator::update()

     m_sni->setTitle(i18n("Microphone"));
     m_sni->setIconByName(iconName);
-    m_sni->setToolTip(QIcon::fromTheme(iconName), allMuted ? i18n("Microphone Muted") : i18n("Microphone"), toolTipForApps(apps));
+    m_sni->setToolTip(QIcon::fromTheme(iconName), toolTipTitle, toolTipForApps(apps));

     if (m_muteAction) {
         m_muteAction->setChecked(allMuted);
-- 
